public class EditDistanceTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void broke(String label, Throwable t) {
        System.out.println("FAIL  " + label + " -- expected a value but got " + t.getClass().getSimpleName());
        failures++;
    }

    public static void main(String[] args) {
        try {
            check("distance(\"kitten\", \"sitting\")", 3, EditDistance.distance("kitten", "sitting"));
            check("distance(\"flaw\", \"lawn\")", 2, EditDistance.distance("flaw", "lawn"));
            check("distance(\"book\", \"back\")", 2, EditDistance.distance("book", "back"));
            check("distance(\"sunday\", \"saturday\")", 3, EditDistance.distance("sunday", "saturday"));
            check("identical strings", 0, EditDistance.distance("same", "same"));
            check("case matters", 1, EditDistance.distance("Cat", "cat"));
            check("empty source", 3, EditDistance.distance("", "abc"));
            check("empty target", 3, EditDistance.distance("abc", ""));
        } catch (Throwable t) {
            broke("distance", t);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

